package cn.zhuatech.salesagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class OutboundActionAuthorizationServiceTest{private final OutboundActionAuthorizationService s=new OutboundActionAuthorizationService();@Test void executesGovernedAction(){var r=s.assess(new OutboundActionAuthorizationService.Request("A1",true,true,false,true,true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(OutboundActionAuthorizationService.Decision.EXECUTE);}@Test void reviewsOperationalGaps(){var r=s.assess(new OutboundActionAuthorizationService.Request("A2",true,true,false,true,true,false,false,false,false,true,false,false));assertThat(r.actions()).hasSize(2);}@Test void blocksUnsafeAction(){var r=s.assess(new OutboundActionAuthorizationService.Request("A3",false,false,true,false,false,true,false,true,false,false,true,true));assertThat(r.blockers()).hasSize(8);}}
